# Image choices use inspected character crops or isolated cells from a 3x2 atlas.
def choice(book, subject, label, cell=None):
    result = {'label': label, 'image': f'assets/books/{book}/art/{book}-{subject}.webp'}
    if cell is not None:
        result['image'] = f'assets/books/{book}/art/{book}-answers.webp'
        result['cell'] = cell
    return result

def atlas(book, cell, label):
    return choice(book, 'answers', label, cell)

def tq(prompt, hint, feedback, correct, other, evidence_page, evidence):
    return (prompt, hint, feedback, correct, other, evidence_page, evidence)

