def clean_page(raw, title, author, poem=False):
    headers = {title, author, 'Русская народная', 'Ганс Христиан Андерсен', 'Шарль Перро', 'Корней Иванович Чуковский'}
    lines = [line.strip() for line in raw.splitlines()]
    lines = [line for line in lines if 'deti-online.com' not in line
             and not re.fullmatch(r'\d+', line)
             and not re.fullmatch(r'\d+\s+часть', line, flags=re.IGNORECASE)
             and line not in headers]
    value = '\n'.join(lines).strip()
    if poem:
        return re.sub(r'\n{3,}', '\n\n', value)
    value = re.sub(r'([А-Яа-яЁё])-\n([А-Яа-яЁё])', r'\1-\2', value)
    return '\n\n'.join(' '.join(part.split()) for part in re.split(r'\n\s*\n', value) if part.strip())


# Authored crops retain a single unmistakable subject. Full source illustrations,
# including their printed notices, remain bundled in assets/books and the PDFs.
SOURCE_CHOICES = {
 'aibolit': {
  'doctor': (14,(400,210,617,707)), 'fox': (2,None), 'rabbit': (4,None),
  'dog': (3,None), 'wolves': (6,None), 'whale': (7,None), 'eagles': (8,None),
  'hippos': (10,None), 'shark': (11,None), 'grasshopper': (12,None),
 },
 'little-red-riding-hood': {'girl': (1,None), 'wolf': (3,None), 'grandmother': (4,None)},
 'turnip': {'grandpa': (7,(155,200,326,392)), 'girl': (7,(426,240,580,402)),
  'dog': (5,(537,382,745,648)), 'cat': (6,(610,488,747,683)),
  'mouse': (7,(451,621,592,721))},
}

def prepare_source_choices():
    for book_id, subjects in SOURCE_CHOICES.items():
        output = ART/book_id/'art'
        output.mkdir(parents=True, exist_ok=True)
        for subject,(number,box) in subjects.items():
            im=Image.open(ROOT/image_path(book_id,number)).convert('RGB')
            if box: im=im.crop(box)
            im.save(output/f'{book_id}-{subject}.webp',quality=95)

def prepare():
    OUT.mkdir(parents=True, exist_ok=True)
    ART.mkdir(parents=True, exist_ok=True)
    reading, listening = [], []
    with tempfile.TemporaryDirectory() as temp:
      for book_id, title, author in SPECS:
        source = ROOT / 'books' / f'{title}.pdf'
        source_text = subprocess.check_output(['pdftotext', '-layout', str(source), '-']).decode().split('\f')
        pages = []
        for index, raw in enumerate(source_text):
            text = clean_page(raw, title, author, poem=book_id == 'aibolit')
            if text:
                pages.append({'sourcePage': index+1, 'text': text, 'image': image_path(book_id, READING_ART[book_id][len(pages)])})
        (ART/book_id/'art').mkdir(parents=True,exist_ok=True)
        shutil.copyfile(source, ART/book_id/f'{book_id}_original.pdf')
        if book_id in {'aibolit','turnip','little-red-riding-hood'}:
            prefix = Path(temp) / book_id
            subprocess.run(['pdfimages','-j',str(source),str(prefix)],check=True)
            for i, path in enumerate(sorted(Path(temp).glob(f'{book_id}-*.jpg'))):
                im=Image.open(path).convert('RGB'); im.save(ROOT / image_path(book_id,i+1), quality=91)
        attribution = f'{author}. «{title}». Текст из предоставленного PDF deti-online.com. Оригинальный файл, авторство и указание источника сохранены.'
        if book_id in {'aibolit','turnip','little-red-riding-hood'}:
            attribution += ' Иллюстрации из того же PDF, исходные подписи deti-online.com сохранены.'
        else:
            attribution += ' Исходный PDF не содержит иллюстраций; рисунки созданы для этого приложения.'
        batches=[]
        assert len(READING_QUESTIONS[book_id]) == (len(pages)+2)//3
        for batch_index, authored in enumerate(READING_QUESTIONS[book_id]):
            assert len(authored)==4
            questions=[]
            for number, (prompt,correct,others,hint,explanation) in enumerate(authored):
                options=list(others); options.insert(number,correct)
                questions.append(dict(prompt=prompt,options=options,answer=number,hint=hint,explanation=explanation))
            batches.append(dict(startPage=batch_index*3,endPage=min(batch_index*3+3,len(pages)),questions=questions))
        common=dict(id=book_id,title=title,language='ru',attribution=attribution,original=f'assets/books/{book_id}/{book_id}_original.pdf',cover=image_path(book_id,1))
        reading.append(dict(**common,author=author,pages=pages,batches=batches))
        scenes=[]
        for i,(text,picture,source_pages) in enumerate(SCENES[book_id]):
            scene_id=f'{book_id}-page-{i+1:02d}'
            assert 15 <= len(text.split()) <= 65, (scene_id,len(text.split()))
            scenes.append(dict(id=scene_id,text=text,image=image_path(book_id,picture),sourcePages=source_pages,audio=f'assets/books/{book_id}/audio/{scene_id}.mp3'))
        questions=[]
        for i,(prompt,hint,feedback,correct,other,evidence_page,evidence) in enumerate(LISTENING_QUESTIONS[book_id]):
            question_id=f'{book_id}-question-{i+1:02d}'; answer=i%2
            choices=[correct,other] if answer==0 else [other,correct]
            questions.append(dict(id=question_id,afterPage=(i//2)*3+2,prompt=prompt,hint=hint,
                guided=f'Давай вместе. Нажми на картинку с зелёной рамкой. {feedback}',feedback=feedback,
                choices=choices,answer=answer,
                evidenceSceneIds=[scenes[evidence_page]['id']],evidence=evidence,
                audio={kind:f'assets/books/{book_id}/audio/{question_id}-{kind}.mp3' for kind in ('prompt','hint','guided','feedback')}))
        assert len(questions)==len(scenes)//3*2
        completion=dict(text=f'Ты послушал всю сказку «{title}» и нашёл картинки! Вот твоя звёздочка за сказку. Можно послушать её снова.',audio=f'assets/books/{book_id}/audio/{book_id}-complete.mp3')
        listening.append(dict(**common,version=1,voice='longanlingxin',model='qwen/qwen-audio-3.0-tts-plus',adaptationNote=NOTES[book_id],pages=scenes,questions=questions,completion=completion))
    prepare_source_choices()
    (OUT/'russian-reading.json').write_text(json.dumps(reading,ensure_ascii=False,indent=2)+'\n')
    (OUT/'russian-listening.json').write_text(json.dumps(listening,ensure_ascii=False,indent=2)+'\n')
    print('Prepared:',[(b['id'],len(b['pages']),sum(len(x['questions']) for x in b['batches'])) for b in reading])
    print('Listening:',[(b['id'],len(b['pages']),len(b['questions'])) for b in listening])

if __name__=='__main__':
    prepare()
